const views = ["phones", "cases", "phones", "chargers", "chargers", "cases", "chargers", "phones"];

function longestFocused(list, maxCategories) {
  const counts = new Map();
  let left = 0;
  let best = 0;
  for (let right = 0; right < list.length; right++) {
    counts.set(list[right], (counts.get(list[right]) ?? 0) + 1);
    while (counts.size > maxCategories) {
      const c = list[left];
      counts.set(c, counts.get(c) - 1);
      if (counts.get(c) === 0) counts.delete(c);
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

console.log(longestFocused(views, 2), longestFocused(views, 3));

