const picks = ["LAG", "LAG", "ABJ", "LAG", "PHC", "PHC", "ABJ", "LAG"];

function shortestCover(events, required) {
  const inside = new Map();
  let covered = 0;
  let left = 0;
  let best = Infinity;
  for (let right = 0; right < events.length; right++) {
    const e = events[right];
    if (required.has(e)) {
      inside.set(e, (inside.get(e) ?? 0) + 1);
      if (inside.get(e) === 1) covered++;
    }
    while (covered === required.size) {
      best = Math.min(best, right - left + 1);
      const out = events[left];
      if (required.has(out)) {
        inside.set(out, inside.get(out) - 1);
        if (inside.get(out) === 0) covered--;
      }
      left++;
    }
  }
  return best === Infinity ? 0 : best;
}

console.log(shortestCover(picks, new Set(["LAG", "ABJ", "PHC"])), shortestCover(picks, new Set(["KAN"])));

