const stops = [9, 14, 6, 11, 20, 4, 13, 7];

function ridersNeeded(list, limit) {
  let riders = 1;
  let load = 0;
  for (const p of list) {
    if (load + p > limit) {
      riders++;
      load = 0;
    }
    load += p;
  }
  return riders;
}

function smallestBusiest(list, riders) {
  let lo = Math.max(...list);
  let hi = list.reduce((a, b) => a + b, 0) + 1;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (ridersNeeded(list, mid) <= riders) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

console.log(smallestBusiest(stops, 3), smallestBusiest(stops, 1));
